import type { FilterExpression } from '@wix/sdk-types'
import type {
  WixDataDistinctOptions,
  WixDataItem,
  WixDataQuerySpec,
} from './types'
import type { SortOrder } from '../types/data-item-types'

/**
 * Options builder for distinct operations.
 *
 * Use this builder to configure distinct behavior such as language, consistency,
 * filters, ordering, and paging.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataDistinctOptionsBuilder {
  /**
   * Sets whether to suppress distinct hooks.
   *
   * When `true`, the distinct operation runs without triggering hooks.
   */
  withSuppressHooks(value: boolean): WixDataDistinctOptionsBuilder
  /**
   * Sets whether to include draft items when retrieving distinct values.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataDistinctOptionsBuilder
  /**
   * Sets app-specific options for the distinct operation.
   * @internal
   */
  withAppOptions(value: Record<string, any>): WixDataDistinctOptionsBuilder
  /**
   * Sets the language used for the distinct operation.
   */
  withLanguage(value: string): WixDataDistinctOptionsBuilder
  /**
   * Sets whether the distinct operation uses a consistent read.
   */
  withConsistentRead(value: boolean): WixDataDistinctOptionsBuilder
  /**
   * Sets whether to return the total count with the distinct results.
   */
  withReturnTotalCount(value: boolean): WixDataDistinctOptionsBuilder
  /**
   * Sets the filter used to retrieve distinct values.
   */
  withFilter(
    value: FilterExpression<WixDataItem, WixDataQuerySpec>
  ): WixDataDistinctOptionsBuilder
  /**
   * Sets the sort order for the distinct results.
   */
  withOrder(value: SortOrder): WixDataDistinctOptionsBuilder
  /**
   * Sets offset-based paging for the distinct results.
   */
  withPaging(value: {
    limit?: number
    offset?: number
  }): WixDataDistinctOptionsBuilder
  /**
   * Sets cursor-based paging for the distinct results.
   */
  withCursorPaging(value: {
    cursor?: string
    limit?: number
  }): WixDataDistinctOptionsBuilder
  /**
   * Builds the distinct options object.
   */
  build(): WixDataDistinctOptions
}

class WixDataDistinctOptionsBuilderImpl
  implements WixDataDistinctOptionsBuilder
{
  constructor(private readonly options: WixDataDistinctOptions = {}) {}

  withSuppressHooks(value: boolean): WixDataDistinctOptionsBuilder {
    return this.copy({ suppressHooks: value })
  }

  withShowDrafts(value: boolean): WixDataDistinctOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  withAppOptions(value: Record<string, any>): WixDataDistinctOptionsBuilder {
    return this.copy({ appOptions: { ...value } })
  }

  withLanguage(value: string): WixDataDistinctOptionsBuilder {
    return this.copy({ language: value })
  }

  withConsistentRead(value: boolean): WixDataDistinctOptionsBuilder {
    return this.copy({ consistentRead: value })
  }

  withReturnTotalCount(value: boolean): WixDataDistinctOptionsBuilder {
    return this.copy({ returnTotalCount: value })
  }

  withFilter(
    value: FilterExpression<WixDataItem, WixDataQuerySpec>
  ): WixDataDistinctOptionsBuilder {
    return this.copy({ filter: value.filter })
  }

  withOrder(value: SortOrder): WixDataDistinctOptionsBuilder {
    return this.copy({ order: value })
  }

  withPaging(value: {
    limit?: number
    offset?: number
  }): WixDataDistinctOptionsBuilder {
    return this.copy({ paging: { ...value } })
  }

  withCursorPaging(value: {
    cursor?: string
    limit?: number
  }): WixDataDistinctOptionsBuilder {
    return this.copy({ cursorPaging: { ...value } })
  }

  build(): WixDataDistinctOptions {
    return {
      ...this.options,
      ...(this.options.appOptions
        ? { appOptions: { ...this.options.appOptions } }
        : {}),
      ...(this.options.paging ? { paging: { ...this.options.paging } } : {}),
      ...(this.options.cursorPaging
        ? { cursorPaging: { ...this.options.cursorPaging } }
        : {}),
    }
  }

  private copy(options: WixDataDistinctOptions): WixDataDistinctOptionsBuilder {
    return new WixDataDistinctOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new distinct options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create a distinct options builder"
 * import { items, DistinctOptionsBuilder } from '@wix/data'
 *
 * const options = DistinctOptionsBuilder()
 *   .withLanguage('en')
 *   .withConsistentRead(true)
 *   .withReturnTotalCount(true)
 *   .withFilter(Filter('status').eq('active'))
 *   .withOrder([{ fieldName: 'status', order: 'asc' }])
 *   .withPaging({ limit: 10, offset: 5 })
 *   .build()
 *
 * const result = await items.distinct('myCollection', 'status', options)
 * ```
 */
export const DistinctOptionsBuilder: () => WixDataDistinctOptionsBuilder = () =>
  new WixDataDistinctOptionsBuilderImpl()
